-- Dados de exemplo para o painel não abrir vazio.
--
-- Os ids NÃO são informados: as colunas são GENERATED BY DEFAULT AS IDENTITY, e um id fixo não
-- avança a sequência, o que faria o próximo cadastro pela API colidir com a chave primária.
-- Por isso as ligações são feitas pelo código do equipamento e pelo nome do plano.
--
-- Datas relativas a hoje, para o agendamento continuar no futuro em qualquer dia da demonstração.

INSERT INTO equipments (code, name, category, current_hours, created_at) VALUES
    ('ESC-001', 'Escavadeira hidráulica 20 t', 'Escavadeira',   4820.0, CURRENT_TIMESTAMP),
    ('GER-001', 'Gerador diesel 180 kVA',      'Gerador',      12350.5, CURRENT_TIMESTAMP),
    ('TRA-001', 'Trator agrícola 110 cv',      'Trator',        2975.0, CURRENT_TIMESTAMP),
    ('CAM-001', 'Caminhão basculante 6x4',     'Caminhão',      8640.0, CURRENT_TIMESTAMP),
    ('EMP-001', 'Empilhadeira a gás 2,5 t',    'Empilhadeira',  1510.0, CURRENT_TIMESTAMP),
    ('COM-001', 'Compressor de ar portátil',   'Compressor',    3205.5, CURRENT_TIMESTAMP);

-- Restante = última manutenção + intervalo - horímetro atual.
-- OVERDUE: restante <= 0 | UPCOMING: restante <= aviso | ON_TIME: restante > aviso
INSERT INTO maintenance_plans (equipment_id, name, interval_hours, warning_hours, last_maintenance_hours, created_at)
SELECT e.id, p.name, p.interval_hours, p.warning_hours, p.last_maintenance_hours, CURRENT_TIMESTAMP
FROM equipments e
JOIN (
              SELECT 'ESC-001' AS code, 'Troca de óleo do motor' AS name, 250.0 AS interval_hours, 25.0 AS warning_hours, 4500.0 AS last_maintenance_hours -- restante  -70,0: OVERDUE
    UNION ALL SELECT 'ESC-001', 'Troca dos filtros hidráulicos',  500.0,  50.0,  4400.0 -- restante   80,0: ON_TIME
    UNION ALL SELECT 'GER-001', 'Revisão geral',                 2000.0, 100.0, 10000.0 -- restante -350,5: OVERDUE
    UNION ALL SELECT 'GER-001', 'Troca de óleo e filtros',        300.0,  30.0, 12070.0 -- restante   19,5: UPCOMING
    UNION ALL SELECT 'TRA-001', 'Troca de óleo do motor',         250.0,  25.0,  2740.0 -- restante   15,0: UPCOMING
    UNION ALL SELECT 'TRA-001', 'Lubrificação geral',             100.0,  10.0,  2900.0 -- restante   25,0: ON_TIME
    UNION ALL SELECT 'CAM-001', 'Troca de óleo do motor',         500.0,  50.0,  8200.0 -- restante   60,0: ON_TIME
    UNION ALL SELECT 'CAM-001', 'Revisão dos freios',            1000.0, 100.0,  8000.0 -- restante  360,0: ON_TIME
    UNION ALL SELECT 'EMP-001', 'Revisão do sistema a gás',       200.0,  20.0,  1320.0 -- restante   10,0: UPCOMING
    UNION ALL SELECT 'COM-001', 'Troca do filtro de ar',          200.0,  20.0,  3000.0 -- restante   -5,5: OVERDUE
) p ON p.code = e.code;

-- Histórico de leituras: a última de cada equipamento é igual ao horímetro atual
INSERT INTO hour_meter_readings (equipment_id, hours, read_at, registered_by, created_at)
SELECT e.id, r.hours, CURRENT_TIMESTAMP - r.days_ago * INTERVAL '1' DAY, r.registered_by, CURRENT_TIMESTAMP
FROM equipments e
JOIN (
              SELECT 'ESC-001' AS code, 4610.0 AS hours, 40 AS days_ago, 'Carlos Lima' AS registered_by
    UNION ALL SELECT 'ESC-001',  4730.0, 20, 'Carlos Lima'
    UNION ALL SELECT 'ESC-001',  4820.0,  2, 'Carlos Lima'
    UNION ALL SELECT 'GER-001', 12110.0, 30, 'Ana Souza'
    UNION ALL SELECT 'GER-001', 12350.5,  1, 'Ana Souza'
    UNION ALL SELECT 'TRA-001',  2910.0, 25, 'Marcos Dias'
    UNION ALL SELECT 'TRA-001',  2975.0,  3, 'Marcos Dias'
    UNION ALL SELECT 'CAM-001',  8390.0, 35, 'Ana Souza'
    UNION ALL SELECT 'CAM-001',  8640.0,  4, 'Ana Souza'
    UNION ALL SELECT 'EMP-001',  1405.0, 28, 'Marcos Dias'
    UNION ALL SELECT 'EMP-001',  1510.0,  2, 'Marcos Dias'
    UNION ALL SELECT 'COM-001',  3120.0, 22, 'Carlos Lima'
    UNION ALL SELECT 'COM-001',  3205.5,  1, 'Carlos Lima'
) r ON r.code = e.code;

-- Concluídas: as horas batem com a última manutenção dos planos acima
INSERT INTO maintenance_records (equipment_id, plan_id, status, scheduled_date, performed_at, hours_at_maintenance, description, responsible, created_at)
SELECT e.id, p.id, 'COMPLETED', CAST(CURRENT_DATE - 62 * INTERVAL '1' DAY AS DATE), CAST(CURRENT_DATE - 60 * INTERVAL '1' DAY AS DATE),
       p.last_maintenance_hours, 'Manutenção preventiva: ' || p.name, 'Oficina Central', CURRENT_TIMESTAMP
FROM maintenance_plans p
JOIN equipments e ON e.id = p.equipment_id
WHERE (e.code = 'ESC-001' AND p.name = 'Troca de óleo do motor')
   OR (e.code = 'CAM-001' AND p.name = 'Troca de óleo do motor')
   OR (e.code = 'COM-001' AND p.name = 'Troca do filtro de ar');

-- Agendadas ligadas a plano: prontas para concluir ou cancelar na demonstração
INSERT INTO maintenance_records (equipment_id, plan_id, status, scheduled_date, description, responsible, created_at)
SELECT e.id, p.id, 'SCHEDULED', CAST(CURRENT_DATE + 3 * INTERVAL '1' DAY AS DATE), 'Agendada: ' || p.name, 'Oficina Central', CURRENT_TIMESTAMP
FROM maintenance_plans p
JOIN equipments e ON e.id = p.equipment_id
WHERE (e.code = 'ESC-001' AND p.name = 'Troca de óleo do motor')
   OR (e.code = 'GER-001' AND p.name = 'Revisão geral');

-- Agendamento cancelado, para o histórico mostrar os três estados
INSERT INTO maintenance_records (equipment_id, plan_id, status, scheduled_date, description, responsible, created_at)
SELECT e.id, p.id, 'CANCELED', CAST(CURRENT_DATE - 10 * INTERVAL '1' DAY AS DATE), 'Agendamento remarcado por falta de peça', 'Oficina Central', CURRENT_TIMESTAMP
FROM maintenance_plans p
JOIN equipments e ON e.id = p.equipment_id
WHERE e.code = 'TRA-001' AND p.name = 'Troca de óleo do motor';

-- Manutenção avulsa (corretiva): sem plano
INSERT INTO maintenance_records (equipment_id, status, scheduled_date, performed_at, hours_at_maintenance, description, responsible, created_at)
SELECT id, 'COMPLETED', CAST(CURRENT_DATE - 15 * INTERVAL '1' DAY AS DATE), CAST(CURRENT_DATE - 15 * INTERVAL '1' DAY AS DATE), 8500.0,
       'Corretiva: troca de mangueira do basculante', 'Oficina Central', CURRENT_TIMESTAMP
FROM equipments
WHERE code = 'CAM-001';
